/**
 * @summary Approve or reject a task output
 */
export const getDecideReviewUrl = (id: number) => {
  return `/api/reviews/${id}/decide`;
};

export const decideReview = async (
  id: number,
  decideReviewBody: DecideReviewBody,
  options?: RequestInit,
): Promise<Review> => {
  return customFetch<Review>(getDecideReviewUrl(id), {
    ...options,
    method: "POST",
    headers: { "Content-Type": "application/json", ...options?.headers },
    body: JSON.stringify(decideReviewBody),
  });
};

export const getDecideReviewMutationOptions = <
  TError = ErrorType<void>,
  TContext = unknown,
>(options?: {
  mutation?: UseMutationOptions<
    Awaited<ReturnType<typeof decideReview>>,
    TError,
    { id: number; data: BodyType<DecideReviewBody> },
    TContext
  >;
  request?: SecondParameter<typeof customFetch>;
}): UseMutationOptions<
  Awaited<ReturnType<typeof decideReview>>,
  TError,
  { id: number; data: BodyType<DecideReviewBody> },
  TContext
> => {
  const mutationKey = ["decideReview"];
  const { mutation: mutationOptions, request: requestOptions } = options
    ? options.mutation &&
      "mutationKey" in options.mutation &&
      options.mutation.mutationKey
      ? options
      : { ...options, mutation: { ...options.mutation, mutationKey } }
    : { mutation: { mutationKey }, request: undefined };

  const mutationFn: MutationFunction<
    Awaited<ReturnType<typeof decideReview>>,
    { id: number; data: BodyType<DecideReviewBody> }
  > = (props) => {
    const { id, data } = props ?? {};

    return decideReview(id, data, requestOptions);
  };

  return { mutationFn, ...mutationOptions };
};

export type DecideReviewMutationResult = NonNullable<
  Awaited<ReturnType<typeof decideReview>>
>;
export type DecideReviewMutationBody = BodyType<DecideReviewBody>;
export type DecideReviewMutationError = ErrorType<void>;

/**
 * @summary Approve or reject a task output
 */
export const useDecideReview = <
  TError = ErrorType<void>,
  TContext = unknown,
>(options?: {
  mutation?: UseMutationOptions<
    Awaited<ReturnType<typeof decideReview>>,
    TError,
    { id: number; data: BodyType<DecideReviewBody> },
    TContext
  >;
  request?: SecondParameter<typeof customFetch>;
}): UseMutationResult<
  Awaited<ReturnType<typeof decideReview>>,
  TError,
  { id: number; data: BodyType<DecideReviewBody> },
  TContext
> => {
  return useMutation(getDecideReviewMutationOptions(options));
};

